package com.danawa.search.analysis.dict

import com.danawa.io.DataInput
import com.danawa.io.DataOutput
import com.danawa.io.InputStreamDataInput
import com.danawa.io.OutputStreamDataOutput
import com.danawa.search.analysis.korean.PosTagProbEntry.PosTag
import com.danawa.search.analysis.korean.PosTagProbEntry.TagProb
import com.danawa.search.analysis.korean.PreResult
import com.danawa.util.CharVector
import org.apache.logging.log4j.Logger
import org.elasticsearch.common.logging.Loggers
import java.io.*
import java.util.*

/**
 * Dictionary for POS tags with probability scores.
 * Used as the system dictionary for Korean morphological analysis.
 */
class TagProbDictionary : Dictionary<TagProb, PreResult<CharSequence>>, ReadableDictionary, WritableDictionary {

    private var _seq: Int = 0
    private var _label: String? = null
    private val ignoreCase: Boolean
    private var probMap: MutableMap<CharSequence, MutableList<TagProb>> = HashMap()
    private var preMap: Map<CharSequence, PreResult<CharSequence>>? = null

    constructor(ignoreCase: Boolean) {
        this.ignoreCase = ignoreCase
    }

    constructor(probMap: Map<CharSequence, List<TagProb>>, ignoreCase: Boolean) {
        this.ignoreCase = ignoreCase
        probMap.forEach { (key, value) ->
            this.probMap[key] = ArrayList(value)
        }
    }

    constructor(file: File, ignoreCase: Boolean) {
        this.ignoreCase = ignoreCase
        if (!file.exists()) {
            logger.error("사전파일이 존재하지 않습니다. file={}", file.absolutePath)
            return
        }
        var inputStream: InputStream? = null
        try {
            inputStream = FileInputStream(file)
            readFrom(inputStream)
        } catch (e: IOException) {
            logger.error("", e)
        } finally {
            try { inputStream?.close() } catch (ignore: Exception) { }
        }
    }

    fun ignoreCase(): Boolean = ignoreCase

    override fun label(): String? = _label

    override fun seq(): Int = _seq

    fun setPreMap(preMap: Map<CharSequence, PreResult<CharSequence>>?) {
        this.preMap = preMap
    }

    fun appendNounEntry(entrySet: Set<CharSequence>?) {
        appendPosTagEntry(entrySet, PosTag.N, TagProb.MAX_PROB)
    }

    override fun appendAdditionalNounEntry(entrySet: Set<CharSequence>?, tokenType: String?) {
        if (entrySet == null) return

        val prob = TagProb.getProb(tokenType)
        if (prob == -1.0) {
            // Not specified, don't add
            return
        }
        appendPosTagEntry(entrySet, PosTag.N, prob)
    }

    fun appendPosTagEntry(entrySet: Set<CharSequence>?, posTag: PosTag, prob: Double) {
        if (entrySet == null) return

        val tagProb = TagProb(posTag, prob)
        for (key in entrySet) {
            putAndReplaceProbMap(key, tagProb)
        }
    }

    fun addSourceEntry(line: String) {
        addSourceEntry(probMap, line, ignoreCase)
    }

    private fun putAndReplaceProbMap(key: CharSequence, tagProb: TagProb) {
        var tagProbList = probMap[key]
        if (tagProbList == null) {
            tagProbList = ArrayList(1)
            tagProbList.add(tagProb)
            probMap[key] = tagProbList
        } else {
            var foundTag = false
            for (i in tagProbList.indices) {
                val oldTagProb = tagProbList[i]
                if (oldTagProb == tagProb) {
                    if (tagProb.prob() > oldTagProb.prob()) {
                        // New tagprob has higher prob, replace
                        tagProbList.removeAt(i)
                    } else {
                        foundTag = true
                    }
                    break
                }
            }
            if (!foundTag) {
                tagProbList.add(tagProb)
            }
        }
    }

    // Return unmodifiable map for final usage
    fun getUnmodifiableDictionary(): Map<CharSequence, List<TagProb>> {
        return Collections.unmodifiableMap(probMap)
    }

    @Throws(IOException::class)
    override fun readFrom(input: InputStream) {
        var dataInput: DataInput? = null
        try {
            val bufferedInput = if (input is BufferedInputStream) input else BufferedInputStream(input)
            dataInput = InputStreamDataInput(bufferedInput)
            probMap = HashMap()

            val size = dataInput.readInt()

            for (entryInx in 0 until size) {
                val key: CharSequence = CharVector(dataInput.readString()).apply {
                    if (ignoreCase) ignoreCase()
                }

                val probLength = dataInput.readInt()
                val probs = ArrayList<TagProb>(probLength)

                for (proInx in 0 until probLength) {
                    probs.add(TagProb(PosTag.valueOf(dataInput.readString()), dataInput.readDouble()))
                }

                probMap[key] = probs
            }
        } finally {
            try { dataInput?.close() } catch (ignore: IOException) { }
        }
    }

    @Throws(IOException::class)
    override fun writeTo(out: OutputStream) {
        var output: DataOutput? = null
        try {
            output = OutputStreamDataOutput(out)
            // Write size of map
            output.writeInt(probMap.size)

            // Write key and value map
            for ((key, tagProbs) in probMap) {
                // Write key
                output.writeString(key.toString())

                // Write values
                output.writeInt(tagProbs.size)
                for (tagProb in tagProbs) {
                    output.writeString(tagProb.posTag().toString())
                    output.writeDouble(tagProb.prob())
                }
            }
        } finally {
            try { output?.close() } catch (ignore: IOException) { }
        }
    }

    override fun find(token: CharSequence): List<TagProb>? = probMap[token]

    override fun findPreResult(token: CharSequence): PreResult<CharSequence>? = preMap?.get(token)

    override fun size(): Int = probMap.size

    override fun setPreDictionary(map: Map<CharSequence, PreResult<CharSequence>>) {
        this.preMap = map
    }

    fun getSeq(): Int = _seq

    fun setSeq(seq: Int) {
        this._seq = seq
    }

    fun getLabel(): String? = _label

    fun setLabel(label: String?) {
        this._label = label
    }

    companion object {
        private val logger: Logger = Loggers.getLogger(TagProbDictionary::class.java, "")

        @JvmStatic
        fun addSourceEntry(
            probMap: MutableMap<CharSequence, MutableList<TagProb>>,
            line: String,
            ignoreCase: Boolean
        ) {
            if (line.startsWith("#") || line.startsWith("//") || line.isEmpty()) {
                return
            }
            val tmp = line.split("\t")
            if (tmp.size != 3) return

            val posTag: PosTag = when {
                tmp[1].startsWith("N") -> PosTag.N
                tmp[1].startsWith("V") -> PosTag.V
                tmp[1].startsWith("M") -> PosTag.M
                tmp[1].startsWith("IC") -> PosTag.IC
                tmp[1].startsWith("J") -> PosTag.J
                tmp[1].startsWith("E") -> PosTag.E
                tmp[1].startsWith("XPN") -> PosTag.XPN
                else -> return
            }

            val key = CharVector(tmp[0].trim())
            if (ignoreCase) {
                key.ignoreCase()
            }

            var prob = tmp[2].trim().toDouble()
            if (key.length == 1) {
                // Single char words: restrict probability. 2014-2-3 swsong
                if (posTag == PosTag.N) {
                    if (prob > -13) {
                        prob = TagProb.MIN_PROB
                    }
                } else {
                    // Non-noun single chars are discarded
                    return
                }
            }

            var tagProbList = probMap[key]
            val tagProb = TagProb(posTag, prob)
            if (tagProbList == null) {
                tagProbList = ArrayList(1)
                probMap[key] = tagProbList
                tagProbList.add(tagProb)
            } else {
                if (tagProbList.contains(tagProb)) {
                    for (i in tagProbList.indices) {
                        val tagProb2 = tagProbList[i]
                        if (tagProb2.posTag() == tagProb.posTag()) {
                            if (tagProb2.prob() < tagProb.prob()) {
                                tagProbList.removeAt(i)
                                tagProbList.add(tagProb)
                                break
                            }
                        }
                    }
                } else {
                    tagProbList.add(tagProb)
                }
            }
        }
    }
}

