     1→package com.danawa.util
     2→
     3→import java.io.Serializable
     4→
     5→/**
     6→ * Mutable view over a char array with optional case-insensitive comparison
     7→ */
     8→class CharVector : CharSequence, Comparable<CharSequence>, Serializable, Cloneable {
     9→
    10→    private var array: CharArray = CharArray(0)
    11→    private var _offset: Int = 0
    12→    private var _length: Int = 0
    13→    protected var hash: Int = 0
    14→    private var ignoreCase: Boolean = false
    15→
    16→    constructor()
    17→
    18→    @JvmOverloads
    19→    constructor(str: CharSequence?, ignoreCase: Boolean = false) {
    20→        if (str != null) {
    21→            array = str.toString().toCharArray()
    22→            _offset = 0
    23→            _length = array.size
    24→        } else {
    25→            array = CharArray(0)
    26→            _offset = 0
    27→            _length = 0
    28→        }
    29→        this.ignoreCase = ignoreCase
    30→    }
    31→
    32→    constructor(array: CharArray) : this(array, 0, array.size)
    33→
    34→    constructor(array: CharArray, ignoreCase: Boolean) : this(array, 0, array.size, ignoreCase)
    35→
    36→    @JvmOverloads
    37→    constructor(array: CharArray, offset: Int, length: Int, ignoreCase: Boolean = false) {
    38→        this.array = array
    39→        this._offset = offset
    40→        this._length = length
    41→        this.hash = 0
    42→        this.ignoreCase = ignoreCase
    43→    }
    44→
    45→    fun init(array: CharArray, offset: Int, length: Int) {
    46→        this.array = array
    47→        this._offset = offset
    48→        this._length = length
    49→        this.hash = 0
    50→    }
    51→
    52→    fun init(offset: Int, length: Int) {
    53→        this._offset = offset
    54→        this._length = length
    55→        this.hash = 0
    56→    }
    57→
    58→    fun offset(offset: Int) {
    59→        this._offset = offset
    60→        this.hash = 0
    61→    }
    62→
    63→    fun length(length: Int) {
    64→        this._length = length
    65→        this.hash = 0
    66→    }
    67→
    68→    fun ignoreCase() {
    69→        if (!ignoreCase) {
    70→            this.ignoreCase = true
    71→            hash = 0
    72→        }
    73→    }
    74→
    75→    fun verifyCase() {
    76→        if (ignoreCase) {
    77→            this.ignoreCase = false
    78→            hash = 0
    79→        }
    80→    }
    81→
    82→    fun isIgnoreCase(): Boolean = ignoreCase
    83→
    84→    override fun hashCode(): Int {
    85→        // HashMap contract: hashCode()와 equals()는 일관성이 있어야 함
    86→        // ignoreCase 상태에 따라 해시 계산 방식 결정
    87→        if (hash > 0) return hash  // 음수 해시값도 캐싱
    88→        var h = 0
    89→        var off = _offset
    90→        for (i in 0 until length) {
    91→            var ch: Int = array[off++].code
    92→            ch = toUpperChar(ch).code
    93→            h = 31 * h + ch
    94→        }
    95→        hash = h
    96→        return h
    97→    }
    98→
    99→    fun trim(): CharVector {
   100→        while (_length > 0 && array[_offset] == ' ') {
   101→            _offset++
   102→            _length--
   103→        }
   104→        while (_length > 0 && array[_offset + _length - 1] == ' ') {
   105→            _length--
   106→        }
   107→        hash = 0
   108→        return this
   109→    }
   110→
   111→    override fun toString(): String {
   112→        return if (_length > 0) {
   113→            String(array, _offset, _length)
   114→        } else {
   115→            ""
   116→        }
   117→    }
   118→
   119→    override fun equals(other: Any?): Boolean {
   120→        if (this === other) return true
   121→        if (other is CharVector) {
   122→            val n = _length
   123→            if (n == other._length) {
   124→                if (ignoreCase || other.ignoreCase) {
   125→                    // 둘중 하나라도 ignorecase이면 ignorecase로 비교한다.
   126→                    for (i in 0 until _length) {
   127→                        if (toUpperChar(get(i).code) != toUpperChar(other[i].code)) {
   128→                            return false
   129→                        }
   130→                    }
   131→                } else {
   132→                    for (i in 0 until _length) {
   133→                        if (get(i) != other[i]) {
   134→                            return false
   135→                        }
   136→                    }
   137→                }
   138→                return true
   139→            }
   140→        }
   141→        return false
   142→    }
   143→
   144→    public override fun clone(): CharVector {
   145→        // share array reference
   146→        val cv = CharVector(array, _offset, _length, ignoreCase)
   147→        cv.hash = hash
   148→        return cv
   149→    }
   150→
   151→    override fun compareTo(other: CharSequence): Int {
   152→        val len1 = this._length
   153→        val len2 = other.length
   154→        val minlen = minOf(len1, len2)
   155→
   156→        for (cinx in 0 until minlen) {
   157→            val c1 = this[cinx]
   158→            val c2 = other[cinx]
   159→            if (c1 != c2) {
   160→                return c1.compareTo(c2)
   161→            }
   162→        }
   163→        return len1.compareTo(len2)
   164→    }
   165→
   166→    override fun get(index: Int): Char {
   167→        var ch = array[_offset + index]
   168→        if (ignoreCase) {
   169→            if (ch in 'a'..'z') {
   170→                ch -= 32
   171→            }
   172→        }
   173→        return ch
   174→    }
