package com.danawa.util

import java.io.Serializable

/**
 * Mutable view over a char array with optional case-insensitive comparison
 */
class CharVector : CharSequence, Comparable<CharSequence>, Serializable, Cloneable {

    private var array: CharArray = CharArray(0)
    private var _offset: Int = 0
    private var _length: Int = 0
    protected var hash: Int = 0
    private var ignoreCase: Boolean = false

    constructor()

    @JvmOverloads
    constructor(str: CharSequence?, ignoreCase: Boolean = false) {
        if (str != null) {
            array = str.toString().toCharArray()
            _offset = 0
            _length = array.size
        } else {
            array = CharArray(0)
            _offset = 0
            _length = 0
        }
        this.ignoreCase = ignoreCase
    }

    constructor(array: CharArray) : this(array, 0, array.size)

    constructor(array: CharArray, ignoreCase: Boolean) : this(array, 0, array.size, ignoreCase)

    @JvmOverloads
    constructor(array: CharArray, offset: Int, length: Int, ignoreCase: Boolean = false) {
        this.array = array
        this._offset = offset
        this._length = length
        this.hash = 0
        this.ignoreCase = ignoreCase
    }

    fun init(array: CharArray, offset: Int, length: Int) {
        this.array = array
        this._offset = offset
        this._length = length
        this.hash = 0
    }

    fun init(offset: Int, length: Int) {
        this._offset = offset
        this._length = length
        this.hash = 0
    }

    fun offset(offset: Int) {
        this._offset = offset
        this.hash = 0
    }

    fun length(length: Int) {
        this._length = length
        this.hash = 0
    }

    fun ignoreCase() {
        if (!ignoreCase) {
            this.ignoreCase = true
            hash = 0
        }
    }

    fun verifyCase() {
        if (ignoreCase) {
            this.ignoreCase = false
            hash = 0
        }
    }

    fun isIgnoreCase(): Boolean = ignoreCase

    override fun hashCode(): Int {
        // HashMap contract: hashCode()와 equals()는 일관성이 있어야 함
        // ignoreCase 상태에 따라 해시 계산 방식 결정
        if (hash > 0) return hash  // 음수 해시값도 캐싱
        var h = 0
        var off = _offset
        for (i in 0 until length) {
            var ch: Int = array[off++].code
            ch = toUpperChar(ch).code
            h = 31 * h + ch
        }
        hash = h
        return h
    }

    fun trim(): CharVector {
        while (_length > 0 && array[_offset] == ' ') {
            _offset++
            _length--
        }
        while (_length > 0 && array[_offset + _length - 1] == ' ') {
            _length--
        }
        hash = 0
        return this
    }

    override fun toString(): String {
        return if (_length > 0) {
            String(array, _offset, _length)
        } else {
            ""
        }
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other is CharVector) {
            val n = _length
            if (n == other._length) {
                if (ignoreCase || other.ignoreCase) {
                    // 둘중 하나라도 ignorecase이면 ignorecase로 비교한다.
                    for (i in 0 until _length) {
                        if (toUpperChar(get(i).code) != toUpperChar(other[i].code)) {
                            return false
                        }
                    }
                } else {
                    for (i in 0 until _length) {
                        if (get(i) != other[i]) {
                            return false
                        }
                    }
                }
                return true
            }
        }
        return false
    }

    public override fun clone(): CharVector {
        // share array reference
        val cv = CharVector(array, _offset, _length, ignoreCase)
        cv.hash = hash
        return cv
    }

    override fun compareTo(other: CharSequence): Int {
        val len1 = this._length
        val len2 = other.length
        val minlen = minOf(len1, len2)

        for (cinx in 0 until minlen) {
            val c1 = this[cinx]
            val c2 = other[cinx]
            if (c1 != c2) {
                return c1.compareTo(c2)
            }
        }
        return len1.compareTo(len2)
    }

    override fun get(index: Int): Char {
        var ch = array[_offset + index]
        if (ignoreCase) {
            if (ch in 'a'..'z') {
                ch -= 32
            }
        }
        return ch
    }

    private fun toUpperChar(ch: Int): Char {
        var ch = ch
        if ((ch <= 'z'.code && ch >= 'a'.code)) {
            // 소문자이면..
            ch -= 32
        }
        return ch.toChar()
    }


    // 내부 공백을 삭제해준다.
    fun removeWhitespaces(): CharVector {
        var len = 0
        for (i in 0 until _length) {
            if (array[_offset + i] != ' ') {
                array[_offset + len++] = array[_offset + i]
            }
        }
        _length = len
        hash = 0
        return this
    }

    fun hasWhitespaces(): Boolean {
        for (i in 0 until _length) {
            if (array[_offset + i] == ' ') {
                return true
            }
        }
        return false
    }

    fun array(): CharArray = array

    fun offset(): Int = _offset

    override val length: Int
        get() = _length

    override fun subSequence(startIndex: Int, endIndex: Int): CharSequence {
        return CharVector().apply {
            this.array = this@CharVector.array
            this._offset = this@CharVector._offset + startIndex
            this._length = endIndex - startIndex + 1
        }
    }

    fun splitByWhitespace(): List<CharVector> = splitByWhitespace(this)

    companion object {
        private const val serialVersionUID = 1L

        @JvmStatic
        fun valueOf(o: Any?): CharVector? {
            return when (o) {
                null -> null
                is CharVector -> o
                else -> CharVector(o.toString())
            }
        }

        @JvmStatic
        fun splitByWhitespace(term: CharVector): List<CharVector> {
            var start = 0
            var isPrevWhitespace = true
            val list = mutableListOf<CharVector>()

            for (i in 0 until term.length) {
                val ch = term[i]
                if (ch == ' ') {
                    if (!isPrevWhitespace) {
                        list.add(CharVector(term.array(), start + term.offset(), i - start, term.isIgnoreCase()))
                    }
                    start = i + 1
                    isPrevWhitespace = true
                } else {
                    isPrevWhitespace = false
                }
            }
            if (!isPrevWhitespace) {
                list.add(CharVector(term.array(), start + term.offset(), term.length - start, term.isIgnoreCase()))
            }
            return list
        }
    }
}

