package com.danawa.util

import com.danawa.search.analysis.dict.TagProbDictionary
import com.danawa.search.analysis.korean.PosTagProbEntry
import java.io.BufferedReader
import java.io.File
import java.io.FileOutputStream
import java.io.FileReader
import java.io.IOException
import java.io.OutputStream
import java.util.HashSet

class SystemDictionaryCompiler {

    @Throws(IOException::class)
    fun compileDictionary(outFile: File) {
        outFile.parentFile?.mkdirs()
        if (!outFile.exists()) {
            outFile.createNewFile()
        }

        val out: OutputStream = FileOutputStream(outFile)
        try {
            val dictionary = loadTagProbDictionary()
            dictionary?.writeTo(out)
        } finally {
            out.close()
        }

        println("바이너리 사전을 생성하였습니다. ${outFile.absolutePath} (${outFile.length()}B)")
    }

    fun loadTagProbDictionary(): TagProbDictionary? {
        return try {
            val dictDir = File(RESOURCE_ROOT, TagProbDictionary::class.java.`package`.name.replace(".", "/"))
            val baseDict = TagProbDictionary(true)
            loadTagProbSource(baseDict, File(dictDir, "0.lnpr_morp.txt"))
            loadTagProbSource(baseDict, File(dictDir, "words-prob.txt"))
            loadTagProbByFileName(baseDict, File(dictDir, "01.N.P11.txt"))
            loadTagProbByFileName(baseDict, File(dictDir, "02.N.MIN.txt"))
            loadTagProbByFileName(baseDict, File(dictDir, "03.N.LOW.txt"))
            loadTagProbByFileName(baseDict, File(dictDir, "04.N.MIN.txt"))
            baseDict
        } catch (e: Exception) {
            System.err.println("ERROR LOADING BASE DICTIONARY : ${e.message}")
            null
        }
    }

    private fun loadTagProbSource(dictionary: TagProbDictionary, file: File) {
        var reader: BufferedReader? = null
        try {
            reader = BufferedReader(FileReader(file))
            var line: String?
            while (reader.readLine().also { line = it } != null) {
                dictionary.addSourceEntry(line!!)
            }
        } catch (e: Exception) {
            System.err.println(e.message)
        } finally {
            try {
                reader?.close()
            } catch (ignore: Exception) {
            }
        }
    }

    private fun loadTagProbByFileName(dictionary: TagProbDictionary, file: File) {
        var reader: BufferedReader? = null
        try {
            val entrySet = HashSet<CharSequence>()
            val fileName = file.name
            val parts = fileName.split("\\.".toRegex())
            val posName = parts[1]
            val probType = parts[2]
            val posTag: PosTagProbEntry.PosTag
            try {
                posTag = PosTagProbEntry.PosTag.valueOf(posName)
            } catch (e: Exception) {
                System.err.println("Undefined pos tag = $posName")
                throw e
            }
            val prob = PosTagProbEntry.TagProb.getProb(probType)

            reader = BufferedReader(FileReader(file))
            var line: String?
            while (reader.readLine().also { line = it } != null) {
                if (line!!.startsWith("#") || line!!.startsWith("//") || line!!.isEmpty()) {
                    continue
                }
                val cv = CharVector(line!!)
                if (dictionary.ignoreCase()) {
                    cv.ignoreCase()
                }
                entrySet.add(cv)
            }
            dictionary.appendPosTagEntry(entrySet, posTag, prob)
        } catch (e: Exception) {
            System.err.println(e.message)
        } finally {
            try {
                reader?.close()
            } catch (ignore: Exception) {
            }
        }
    }

    companion object {
        @JvmField
        val RESOURCE_ROOT = File("src/test/resources")

        @JvmStatic
        fun main(args: Array<String>) {
            val compiler = SystemDictionaryCompiler()
            val path = if (args.isNotEmpty()) args[0] else "product.dict"
            val outFile = File(path)
            try {
                compiler.compileDictionary(outFile)
            } catch (ex: Exception) {
                System.err.println("시스템 사전생성 실패: ${ex.message}")
            }
        }
    }
}

