package com.danawa.search.analysis.korean

import java.io.Serializable

/**
 * POS tag with probability entry for Korean morphological analysis
 */
class PosTagProbEntry : Serializable {
    @JvmField
    var tagProb: TagProb? = null

    @JvmField
    var next: PosTagProbEntry? = null

    @JvmField
    var key: CharSequence? = null

    constructor()

    constructor(tagProb: TagProb?) {
        this.tagProb = tagProb
    }

    constructor(tagProb: TagProb?, cvKey: CharSequence?) {
        this.tagProb = tagProb
        this.key = cvKey
    }

    fun set(tagProb: TagProb?) {
        this.tagProb = tagProb
    }

    fun get(): TagProb? = tagProb

    fun next(next: TagProb?): PosTagProbEntry {
        val newEntry = PosTagProbEntry(next)
        newEntry.key = this.key
        this.next = newEntry
        return newEntry
    }

    fun next(): PosTagProbEntry? = next

    fun contains(posTag: TagProb?): Boolean {
        var nextTagEntry: PosTagProbEntry? = this
        while (nextTagEntry != null) {
            if (nextTagEntry.get() === posTag) {
                return true
            }
            nextTagEntry = nextTagEntry.next()
        }
        return false
    }

    fun posContains(posTag: PosTag): Boolean {
        var nextTagEntry: PosTagProbEntry? = this
        while (nextTagEntry != null) {
            if (nextTagEntry.get()?.posTag == posTag) {
                return true
            }
            nextTagEntry = nextTagEntry.next()
        }
        return false
    }

    enum class PosTag {
        SOE, UNK, N, V, M, IC, J, E, EP, X, ALPHA /* 영문 */, XPN, EOE, GUESS, DIGIT, SYMBOL
    }

    class TagProb : Serializable {
        @JvmField
        val posTag: PosTag

        private val prob: Double

        @JvmOverloads
        constructor(posTag: PosTag, prob: Double = MIN_PROB) {
            this.posTag = posTag
            this.prob = prob
        }

        fun posTag(): PosTag = posTag

        fun prob(): Double = prob

        override fun equals(other: Any?): Boolean {
            if (other !is TagProb) return false
            // 태그만 같다면 같은것으로 본다.
            return other.posTag == this.posTag
        }

        override fun hashCode(): Int = posTag.hashCode()

        override fun toString(): String = "${posTag.name}[$prob]"

        fun toShortString(): String = posTag.name

        companion object {
            private const val serialVersionUID = 1L

            const val MAX_PROB = -5.0
            const val HIGH_PROB = -8.0
            const val P11_PROB = -11.0
            const val P12_PROB = -12.0
            const val MID_PROB = -13.0
            const val LOW_PROB = -14.0
            const val MIN_PROB = -16.0

            @JvmField
            val UNK = TagProb(PosTag.UNK)

            @JvmField
            val GUESS = TagProb(PosTag.GUESS)

            @JvmField
            val DIGIT = TagProb(PosTag.DIGIT, HIGH_PROB)

            @JvmField
            val ALPHA = TagProb(PosTag.ALPHA, HIGH_PROB)

            @JvmField
            val SYMBOL = TagProb(PosTag.SYMBOL)

            @JvmField
            val JOSA = TagProb(PosTag.J, MID_PROB)

            @JvmStatic
            fun getProb(probType: String?): Double {
                if (probType.isNullOrEmpty()) {
                    return -1.0
                }
                return when (probType.lowercase()) {
                    "max" -> MAX_PROB
                    "high" -> HIGH_PROB
                    "mid" -> MID_PROB
                    "p11" -> P11_PROB
                    "p12" -> P12_PROB
                    "low" -> LOW_PROB
                    "min" -> MIN_PROB
                    else -> MIN_PROB
                }
            }
        }
    }

    companion object {
        private const val serialVersionUID = 1L
    }
}

package com.danawa.search.analysis.product

import com.danawa.search.analysis.dict.ProductNameDictionary
import com.danawa.search.analysis.dict.SpaceDictionary
import com.danawa.search.analysis.korean.KoreanWordExtractor
import com.danawa.util.CharVector
import com.danawa.util.TestUtil
import org.junit.jupiter.api.BeforeAll
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.TestInstance

/**
 * 사전 조회 디버깅을 위한 테스트
 * '삼성전자' -> '삼성전', '자' 오분석 원인 추적
 */
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class DictionaryDebugTest {

    private var dictionary: ProductNameDictionary? = null
    private lateinit var extractor: KoreanWordExtractor

    @BeforeAll
    fun setup() {
        dictionary = TestUtil.loadDictionary()
        extractor = KoreanWordExtractor(dictionary)
    }

    @Test
    fun `사전에 삼성, 전자, 삼성전자 존재 여부 확인`() {
        val testWords = listOf("삼성", "전자", "삼성전자", "삼성전", "자", "오디세이")

        println("=" .repeat(60))
        println("사전 조회 테스트")
        println("=".repeat(60))

        for (word in testWords) {
            val cv = CharVector(word)
            val result = dictionary?.find(cv)

            println("\n[$word]")
            println("  CharVector: offset=${cv.offset()}, length=${cv.length}, ignoreCase=${cv.isIgnoreCase()}")
            println("  hashCode: ${cv.hashCode()}")
            println("  사전 조회 결과: ${result ?: "NOT FOUND"}")

            if (result != null) {
                for (tagProb in result) {
                    println("    - ${tagProb.posTag()}: ${tagProb.prob()}")
                }
            }
        }
        println("\n" + "=".repeat(60))
    }

    @Test
    fun `CharVector hashCode-equals 일관성 테스트`() {
        println("\n" + "=".repeat(60))
        println("CharVector hashCode/equals 일관성 테스트")
        println("=".repeat(60))

        // 같은 문자열로 두 개의 CharVector 생성
        val cv1 = CharVector("삼성")
        val cv2 = CharVector("삼성")

        println("\ncv1 = CharVector(\"삼성\")")
        println("cv2 = CharVector(\"삼성\")")
        println("cv1.hashCode() = ${cv1.hashCode()}")
        println("cv2.hashCode() = ${cv2.hashCode()}")
        println("cv1 == cv2: ${cv1 == cv2}")
        println("cv1.equals(cv2): ${cv1.equals(cv2)}")

        // ignoreCase 설정 테스트
        val cv3 = CharVector("삼성", true)
        val cv4 = CharVector("삼성", false)

        println("\ncv3 = CharVector(\"삼성\", ignoreCase=true)")
        println("cv4 = CharVector(\"삼성\", ignoreCase=false)")
        println("cv3.hashCode() = ${cv3.hashCode()}")
        println("cv4.hashCode() = ${cv4.hashCode()}")
        println("cv3 == cv4: ${cv3 == cv4}")

        // HashMap 조회 시뮬레이션
        val map = HashMap<CharSequence, String>()
        map[cv1] = "found"

        println("\nHashMap 테스트:")
        println("map[cv1] = \"found\"")
        println("map[cv2] = ${map[cv2]}")
        println("map[cv3] = ${map[cv3]}")
        println("map[cv4] = ${map[cv4]}")

        println("\n" + "=".repeat(60))
    }

    @Test
    fun `KoreanWordExtractor로 삼성전자 분석`() {
        println("\n" + "=".repeat(60))
        println("KoreanWordExtractor 분석 테스트")
        println("=".repeat(60))

        val testText = "삼성전자"
        val chars = testText.toCharArray()

        println("\n입력: $testText")
        println("문자 배열: ${chars.contentToString()}")

        val result = extractor.setInput(chars, 0, chars.size)
        println("setInput 결과: $result")

        if (result != -1) {
            var entry: KoreanWordExtractor.ExtractedEntry? = extractor.extract()
            var index = 0
            println("\n분석 결과:")
            while (entry != null) {
                val word = String(chars, entry.offset(), entry.column())
                println("  [$index] '$word' - ${entry.tagProb()?.posTag()}: ${entry.tagProb()?.prob()}")
                entry = entry.next()
                index++
            }
        } else {
            println("  분석 실패")
        }

        println("\n" + "=".repeat(60))
    }

    @Test
    fun `사전 키 목록 샘플 출력`() {
        println("\n" + "=".repeat(60))
        println("사전 키 샘플 (처음 20개)")
        println("=".repeat(60))

        // systemDictionary에서 키 샘플 출력
        // ProductNameDictionary가 CommonDictionary를 상속하므로 직접 접근 어려움
        // find()로 특정 단어들 확인

        val sampleWords = listOf(
            "삼", "성", "전", "자",  // 개별 글자
            "삼성", "전자",          // 조합
            "삼성전", "성전자",      // 다른 조합
            "samsung", "Samsung"    // 영문
        )

        for (word in sampleWords) {
            val cv = CharVector(word)
            val result = dictionary?.find(cv)
            val status = if (result != null) "O" else "X"
            println("  [$status] '$word' (hashCode=${cv.hashCode()})")
        }

        println("\n" + "=".repeat(60))
    }

    @Test
    fun `SpaceDictionary 삼성전자 조회 테스트`() {
        println("\n" + "=".repeat(60))
        println("SpaceDictionary (분리어 사전) 조회 테스트")
        println("=".repeat(60))

        val spaceDictionary = dictionary?.getDictionary(
            ProductNameDictionary.DICT_SPACE,
            SpaceDictionary::class.java
        )

        if (spaceDictionary == null) {
            println("SpaceDictionary가 로드되지 않았습니다.")
            println("=".repeat(60))
            return
        }

        println("\nSpaceDictionary 정보:")
        println("  map size: ${spaceDictionary.map().size}")
        println("  wordSet size: ${spaceDictionary.getWordSet().size}")
        println("  ignoreCase: ${spaceDictionary.ignoreCase()}")

        val testKeys = listOf("삼성전자", "삼성 전자", "전자", "삼성")

        println("\n분리어 사전 조회:")
        for (keyStr in testKeys) {
            // ignoreCase = true로 조회
            val keyTrue = CharVector(keyStr, true)
            val foundTrue = spaceDictionary.containsKey(keyTrue)
            val valuesTrue = spaceDictionary[keyTrue]

            // ignoreCase = false로 조회
            val keyFalse = CharVector(keyStr, false)
            val foundFalse = spaceDictionary.containsKey(keyFalse)

            println("\n  Key: '$keyStr'")
            println("    ignoreCase=true:  found=$foundTrue, values=${valuesTrue?.map { it.toString() }}")
            println("    ignoreCase=false: found=$foundFalse")
            println("    hashCode (true): ${keyTrue.hashCode()}, hashCode (false): ${keyFalse.hashCode()}")
        }

        // 사전에 있는 키 샘플 출력
        println("\n분리어 사전 키 샘플 (처음 10개):")
        var count = 0
        for ((key, values) in spaceDictionary.map()) {
            if (count >= 10) break
            println("  '$key' -> ${values.map { it.toString() }}")
            count++
        }

        println("\n" + "=".repeat(60))
    }
}

package com.danawa.util

import com.danawa.search.analysis.dict.CompoundDictionary
import com.danawa.search.analysis.dict.ProductNameDictionary
import com.danawa.search.analysis.dict.SetDictionary
import com.danawa.search.analysis.dict.SpaceDictionary
import com.danawa.search.analysis.dict.SynonymDictionary
import com.danawa.search.analysis.dict.TagProbDictionary
import com.danawa.search.analysis.korean.PosTagProbEntry.PosTag
import com.danawa.search.analysis.korean.PosTagProbEntry.TagProb
import org.apache.logging.log4j.Level
import org.apache.logging.log4j.LogManager
import org.apache.logging.log4j.core.LoggerContext
import org.elasticsearch.common.logging.Loggers
import org.json.JSONObject
import java.io.BufferedReader
import java.io.File
import java.io.FileReader
import java.util.Properties

object TestUtil {

    private val logger = Loggers.getLogger(TestUtil::class.java, "")

    init {
        logger.trace("init TestUtil..")
    }

    const val SYSPROP_LAUNCH_FOR_BUILD = "SYSPROP_LAUNCH_FOR_BUILD"
    const val SYSPROP_TEST_DICTIONARY_SETTING = "SYSPROP_TEST_DICTIONARY_SETTING"
    const val SYSPROP_TEST_DICTIONARY_LOAD_EXTRA = "SYSPROP_TEST_DICTIONARY_LOAD_EXTRA"
    const val SYSPROP_SAMPLE_TEXT_PATH = "SYSPROP_SAMPLE_TEXT_PATH"
    const val LOG_LEVEL = "LOG_LEVEL"
    val LOG_LEVEL_INFO: String = Level.INFO.name()
    val LOG_LEVEL_DEBUG: String = Level.DEBUG.name()
    val LOG_LEVEL_TRACE: String = Level.TRACE.name()
    const val HIGH = "HIGH"
    const val NONE = "NONE"
    const val INTERNAL = "INTERNAL"
    val RESOURCE_ROOT = File("src/test/resources")

    const val T = "true"
    const val F = "false"
    const val Y = "y"

    const val CLASS_SUFFIX = ".class"

    @JvmStatic
    fun launchForBuild(): Boolean {
        return false
        // return T == getSystemProperty(SYSPROP_LAUNCH_FOR_BUILD, "false")
    }

    @JvmStatic
    @JvmOverloads
    fun getSystemProperty(key: String, def: String? = null): String? {
        var ret = System.getProperty(key)
        if (ret == null || ret == "") {
            ret = def
        }
        return ret
    }

    @JvmStatic
    @JvmOverloads
    fun getFileByProperty(key: String, def: String? = null): File? {
        val path = getSystemProperty(key)
        return when {
            path != null -> File(path)
            def != null -> File(def)
            else -> null
        }
    }

    @JvmStatic
    fun getFileByPath(path: String?, def: String?): File? {
        return when {
            path != null -> File(path)
            def != null -> File(def)
            else -> null
        }
    }

    @JvmStatic
    fun getFileByClass(cls: Class<*>, fileName: String): File? {
        return try {
            val className = cls.simpleName
            val url = cls.getResource("$className$CLASS_SUFFIX")
            var ret = File(url!!.file)
            ret = File(ret.parentFile, fileName)
            ret
        } catch (ignore: Exception) {
            null
        }
    }

    @JvmStatic
    fun getFileByRoot(cls: Class<*>, path: String): File {
        return File(ResourceResolver.getResourceRoot(cls), path)
    }

    @JvmStatic
    fun readProperties(file: File): Properties? {
        return ResourceResolver.readProperties(file)
    }

    @JvmStatic
    fun readYmlConfig(file: File): JSONObject? {
        return ResourceResolver.readYmlConfig(file)
    }

    @JvmStatic
    fun setLogLevel(levelStr: String?, vararg classes: Class<*>) {
        val level = Level.toLevel(levelStr, Level.DEBUG)
        val ctx = LogManager.getContext(false) as LoggerContext
        val config = ctx.configuration
        val loggerConfig = config.getLoggerConfig(LogManager.ROOT_LOGGER_NAME)
        loggerConfig.level = level
        for (cls in classes) {
            Loggers.setLevel(Loggers.getLogger(cls, ""), level)
        }
        ctx.updateLoggers()
    }

    private fun loadTagProbSource(dictionary: TagProbDictionary, file: File) {
        var reader: BufferedReader? = null
        try {
            reader = BufferedReader(FileReader(file))
            var line: String?
            while (reader.readLine().also { line = it } != null) {
                dictionary.addSourceEntry(line!!)
            }
        } catch (e: Exception) {
            logger.error("", e)
        } finally {
            try {
                reader?.close()
            } catch (ignore: Exception) {
            }
        }
    }

    private fun loadTagProbByFileName(dictionary: TagProbDictionary, file: File) {
        var reader: BufferedReader? = null
        try {
            val entrySet = HashSet<CharSequence>()
            val fileName = file.name
            val parts = fileName.split("\\.".toRegex())
            val posName = parts[1]
            val probType = parts[2]
            val posTag: PosTag
            try {
                posTag = PosTag.valueOf(posName)
            } catch (e: Exception) {
                logger.error("Undefined pos tag = {}", posName)
                throw e
            }
            val prob = TagProb.getProb(probType)

            reader = BufferedReader(FileReader(file))
            var line: String?
            while (reader.readLine().also { line = it } != null) {
                if (line!!.startsWith("#") || line!!.startsWith("//") || line!!.isEmpty()) {
                    continue
                }
                val cv = CharVector(line)
                if (dictionary.ignoreCase()) {
                    cv.ignoreCase()
                }
                entrySet.add(cv)
            }
            dictionary.appendPosTagEntry(entrySet, posTag, prob)
        } catch (e: Exception) {
            logger.error("", e)
        } finally {
            try {
                reader?.close()
            } catch (ignore: Exception) {
            }
        }
    }

    /**
     * Provides additional dictionary loading functionality since words cannot be directly added to compiled dictionaries.
     */
    @JvmStatic
    fun loadExtraDictionary(dictionary: ProductNameDictionary): ProductNameDictionary {
        val dictDir = File(RESOURCE_ROOT, "dict_extra")
        logger.debug("Extra dict dir:{}", dictDir)

        // User dictionary
        val userDict = SetDictionary(true)
        userDict.loadSource(File(dictDir, "user.txt"))
        dictionary.addDictionary(ProductNameDictionary.DICT_USER, userDict)
        dictionary.appendAdditionalNounEntry(userDict.set(), HIGH)

        // Synonym dictionary
        val synonymDict = SynonymDictionary(true)
        synonymDict.loadSource(File(dictDir, "synonym.txt"))
        dictionary.addDictionary(ProductNameDictionary.DICT_SYNONYM, synonymDict)
        dictionary.appendAdditionalNounEntry(synonymDict.getWordSet(), HIGH)

        // Unit dictionary
        val unitDict = SetDictionary(true)
        unitDict.loadSource(File(dictDir, "unit.txt"))
        dictionary.addDictionary(ProductNameDictionary.DICT_UNIT, unitDict)

        // Unit synonym dictionary
        val unitSynDict = SynonymDictionary(true)
        unitSynDict.loadSource(File(dictDir, "unit_synonym.txt"))
        dictionary.addDictionary(ProductNameDictionary.DICT_UNIT_SYNONYM, unitSynDict)

        // Space dictionary
        val spaceDict = SpaceDictionary(true)
        spaceDict.loadSource(File(dictDir, "space.txt"))
        dictionary.addDictionary(ProductNameDictionary.DICT_SPACE, spaceDict)

        // Compound noun dictionary
        val compDict = CompoundDictionary(true)
        compDict.loadSource(File(dictDir, "compound.txt"))
        dictionary.addDictionary(ProductNameDictionary.DICT_COMPOUND, compDict)

        return dictionary
    }

    @JvmStatic
    fun loadInternalDictionary(): ProductNameDictionary? {
        return try {
            val dictDir = File(
                RESOURCE_ROOT,
                TagProbDictionary::class.java.getPackage().name.replace(".", "/")
            )
            val baseDict = TagProbDictionary(true)
            loadTagProbSource(baseDict, File(dictDir, "0.lnpr_morp.txt"))
            loadTagProbSource(baseDict, File(dictDir, "words-prob.txt"))
            loadTagProbByFileName(baseDict, File(dictDir, "01.N.P11.txt"))
            loadTagProbByFileName(baseDict, File(dictDir, "02.N.MIN.txt"))
            loadTagProbByFileName(baseDict, File(dictDir, "03.N.LOW.txt"))
            ProductNameDictionary(baseDict)
        } catch (e: Exception) {
            logger.debug("ERROR LOADING BASE DICTIONARY : {}", e.message)
            null
        }
    }

    @JvmStatic
    fun loadDictionary(): ProductNameDictionary? {
        var dictionary: ProductNameDictionary? = null
        var path = getSystemProperty(SYSPROP_TEST_DICTIONARY_SETTING)
        var propFile: File? = null
        val loadType: Int

        /**
         * Loading dictionary during test execution
         *   In IntelliJ:
         *     Modify Run Configuration -> VM options: add
         *     -DSYSPROP_TEST_DICTIONARY_SETTING=C:/{{plugin_path}}/product-name-dictionary.yml
         *
         *   In Eclipse:
         *     Run -> Run Configurations -> Arguments -> VM arguments: add
         *     -DSYSPROP_TEST_DICTIONARY_SETTING=C:/{{plugin_path}}/product-name-dictionary.yml
         *
         *   In VSCode:
         *     In .vscode/settings.json file: add
         *     {
         *       "java.test.config": {
         *         "vmargs": [
         *           -DSYSPROP_TEST_DICTIONARY_SETTING=C:/{{plugin_path}}/product-name-dictionary.yml
         *         ]
         *       }
         *     }
         *
         * 1. If not specified: Load internally compiled dictionary (src/test/resources/product-name-dictionary.yml)
         *   -DSYSPROP_TEST_DICTIONARY_SETTING
         *
         * 2. If directly specified: Load external dictionary
         *   -DSYSPROP_TEST_DICTIONARY_SETTING=C:/Temp/analysis-product/product-name-dictionary.yml
         *
         * 3. If set to INTERNAL: Load text-based dictionary
         *   -DSYSPROP_TEST_DICTIONARY_SETTING=INTERNAL
         */
        when {
            INTERNAL == path -> {
                // 3. INTERNAL TEXT BASED DICTIONARY
                loadType = 1
            }
            path != null && path != "" -> {
                // 2. EXTERNAL DICTIONARY
                propFile = getFileByPath(path, null)
                loadType = 0
            }
            else -> {
                // 1. INTERNAL COMPILED BINARY
                path = File(RESOURCE_ROOT, "product-name-dictionary.yml").absolutePath
                propFile = getFileByPath(path, null)
                loadType = 0
            }
        }

        try {
            dictionary = if (loadType == 0) {
                val prop = readYmlConfig(propFile!!)
                ProductNameDictionary.loadDictionary(propFile.parentFile, prop)
            } else {
                loadInternalDictionary()
            }
        } catch (e: Exception) {
            logger.debug("ERROR LOADING DICTIONARY : {}", e.message)
        }

        /**
         * If additional word loading is not needed in test dictionary, specify:
         * -DSYSPROP_TEST_DICTIONARY_LOAD_EXTRA=NONE
         */
        if (NONE != getSystemProperty(SYSPROP_TEST_DICTIONARY_LOAD_EXTRA)) {
            loadExtraDictionary(dictionary!!)
        }
        return dictionary
    }
}

