package com.danawa.io

import java.io.IOException
import java.io.InputStream
import java.util.*

/**
 * Abstract base class for performing read operations of Lucene's low-level data types.
 *
 * DataInput may only be used from one thread, because it is not thread safe
 * (it keeps internal state like file position). To allow multithreaded use,
 * every DataInput instance must be cloned before used in another thread.
 */
abstract class DataInput : InputStream(), Cloneable {

    /**
     * Reads and returns a single byte.
     */
    @Throws(IOException::class)
    abstract fun readByte(): Byte

    @Throws(IOException::class)
    abstract fun length(): Long

    @Throws(IOException::class)
    open fun position(): Long {
        throw UnsupportedOperationException()
    }

    @Throws(IOException::class)
    open fun seek(position: Long) {
        throw UnsupportedOperationException()
    }

    @Throws(IOException::class)
    override fun read(): Int = readByte().toInt()

    /**
     * Reads a specified number of bytes into an array at the specified offset.
     */
    @Throws(IOException::class)
    abstract fun readBytes(b: ByteArray, offset: Int, len: Int)

    @Throws(IOException::class)
    fun readBytes(dst: BytesBuffer) {
        readBytes(dst.bytes, dst.offset, dst.length())
    }

    /**
     * Reads a specified number of bytes into an array at the specified offset
     * with control over whether the read should be buffered.
     */
    @Throws(IOException::class)
    open fun readBytes(b: ByteArray, offset: Int, len: Int, useBuffer: Boolean) {
        // Default to ignoring useBuffer entirely
        readBytes(b, offset, len)
    }

    /**
     * Reads two bytes and returns a short.
     */
    @Throws(IOException::class)
    fun readShort(): Short {
        return (((readByte().toInt() and 0xFF) shl 8) or (readByte().toInt() and 0xFF)).toShort()
    }

    /**
     * Reads four bytes and returns an int.
     */
    @Throws(IOException::class)
    fun readInt(): Int {
        return ((readByte().toInt() and 0xFF) shl 24) or
                ((readByte().toInt() and 0xFF) shl 16) or
                ((readByte().toInt() and 0xFF) shl 8) or
                (readByte().toInt() and 0xFF)
    }

    /**
     * Reads an int stored in variable-length format.
     */
    @Throws(IOException::class)
    fun readVInt(): Int {
        var b = readByte()
        if (b >= 0) return b.toInt()
        var i = b.toInt() and 0x7F
        b = readByte()
        i = i or ((b.toInt() and 0x7F) shl 7)
        if (b >= 0) return i
        b = readByte()
        i = i or ((b.toInt() and 0x7F) shl 14)
        if (b >= 0) return i
        b = readByte()
        i = i or ((b.toInt() and 0x7F) shl 21)
        if (b >= 0) return i
        b = readByte()
        i = i or ((b.toInt() and 0x0F) shl 28)
        if ((b.toInt() and 0xF0) == 0) return i
        throw IOException("Invalid vInt detected (too many bits)")
    }

    /**
     * Reads eight bytes and returns a long.
     */
    @Throws(IOException::class)
    fun readLong(): Long {
        return (readInt().toLong() shl 32) or (readInt().toLong() and 0xFFFFFFFFL)
    }

    /**
     * Reads a long stored in variable-length format.
     */
    @Throws(IOException::class)
    fun readVLong(): Long {
        var b = readByte()
        if (b >= 0) return b.toLong()
        var i = (b.toLong() and 0x7FL)
        b = readByte()
        i = i or ((b.toLong() and 0x7FL) shl 7)
        if (b >= 0) return i
        b = readByte()
        i = i or ((b.toLong() and 0x7FL) shl 14)
        if (b >= 0) return i
        b = readByte()
        i = i or ((b.toLong() and 0x7FL) shl 21)
        if (b >= 0) return i
        b = readByte()
        i = i or ((b.toLong() and 0x7FL) shl 28)
        if (b >= 0) return i
        b = readByte()
        i = i or ((b.toLong() and 0x7FL) shl 35)
        if (b >= 0) return i
        b = readByte()
        i = i or ((b.toLong() and 0x7FL) shl 42)
        if (b >= 0) return i
        b = readByte()
        i = i or ((b.toLong() and 0x7FL) shl 49)
        if (b >= 0) return i
        b = readByte()
        i = i or ((b.toLong() and 0x7FL) shl 56)
        if (b >= 0) return i
        throw IOException("Invalid vLong detected (negative values disallowed)")
    }

    @Throws(IOException::class)
    fun readFloat(): Float = Float.fromBits(readInt())

    @Throws(IOException::class)
    fun readDouble(): Double = Double.fromBits(readLong())

    @Throws(IOException::class)
    fun readBoolean(): Boolean = readByte().toInt() != 0

    @Throws(IOException::class)
    fun readUTF8String(): String {
        val charCount = readVInt()
        val chars = CachedCharArray.getCharArray(charCount)
        var charIndex = 0
        while (charIndex < charCount) {
            val c = readByte().toInt() and 0xff
            when (c shr 4) {
                0, 1, 2, 3, 4, 5, 6, 7 -> chars[charIndex++] = c.toChar()
                12, 13 -> chars[charIndex++] = ((c and 0x1F) shl 6 or (readByte().toInt() and 0x3F)).toChar()
                14 -> chars[charIndex++] = ((c and 0x0F) shl 12 or ((readByte().toInt() and 0x3F) shl 6) or (readByte().toInt() and 0x3F)).toChar()
            }
        }
        return String(chars, 0, charCount)
    }

    // ascii는 1byte로 읽고 나머지는 2byte로 읽는다.
    @Throws(IOException::class)
    fun readString(): String = String(readUString())

    /**
     * Returns a clone of this stream.
     */
    public override fun clone(): DataInput {
        try {
            return super.clone() as DataInput
        } catch (e: CloneNotSupportedException) {
            throw Error("This cannot happen: Failing to clone DataInput")
        }
    }

    @Throws(IOException::class)
    fun readStringStringMap(): Map<String, String> {
        val map = HashMap<String, String>()
        val count = readInt()
        for (i in 0 until count) {
            val key = readString()
            val value = readString()
            map[key] = value
        }
        return map
    }

    @Throws(IOException::class)
    fun readStringSet(): Set<String> {
        val set = HashSet<String>()
        val count = readInt()
        for (i in 0 until count) {
            set.add(readString())
        }
        return set
    }

    @Suppress("UNCHECKED_CAST")
    @Throws(IOException::class)
    fun readMap(): Map<String, Any?> = readGenericValue() as Map<String, Any?>

    @Throws(IOException::class)
    fun readGenericValue(): Any? {
        return when (val type = readByte().toInt()) {
            -1 -> null
            0 -> readString()
            1 -> readInt()
            2 -> readLong()
            3 -> readFloat()
            4 -> readDouble()
            5 -> readBoolean()
            6 -> {
                val bytesSize = readVInt()
                val value = ByteArray(bytesSize)
                readBytes(value, 0, bytesSize)
                value
            }
            7 -> {
                val size = readVInt()
                val list = ArrayList<Any?>(size)
                for (i in 0 until size) {
                    list.add(readGenericValue())
                }
                list
            }
            8 -> {
                val size = readVInt()
                val array = arrayOfNulls<Any>(size)
                for (i in 0 until size) {
                    array[i] = readGenericValue()
                }
                array
            }
            9 -> {
                val size = readVInt()
                val map = LinkedHashMap<String, Any?>(size)
                for (i in 0 until size) {
                    map[readString()] = readGenericValue()
                }
                map
            }
            10 -> {
                val size = readVInt()
                val map = HashMap<String, Any?>(size)
                for (i in 0 until size) {
                    map[readString()] = readGenericValue()
                }
                map
            }
            11 -> readByte()
            12 -> Date(readLong())
            14 -> {
                val size = readVInt()
                val b = BytesBuffer(size)
                readBytes(b)
                b
            }
            16 -> readShort()
            else -> throw IOException("Can't read unknown type [$type]")
        }
    }

    @Throws(IOException::class)
    fun skipVIntData() {
        val len = readVInt()
        for (i in 0 until len) {
            readByte()
        }
    }

    @Throws(IOException::class)
    fun readAStrings(): String {
        val len = readVInt()
        val cs = CharArray(len)
        for (i in 0 until len) {
            cs[i] = readByte().toInt().toChar()
        }
        return String(cs)
    }

    @Throws(IOException::class)
    fun readAString(): CharArray {
        val len = readVInt()
        val cs = CharArray(len)
        for (i in 0 until len) {
            cs[i] = readByte().toInt().toChar()
        }
        return cs
    }

    @Throws(IOException::class)
    fun readUString(): CharArray {
        val byteSize = readVInt()
        val cs = CharArray(byteSize / 2)
        for (i in cs.indices) {
            cs[i] = readShort().toInt().toChar()
        }
        return cs
    }

    @Throws(IOException::class)
    fun readAChar(): Char = readByte().toInt().toChar()

    @Throws(IOException::class)
    fun readUChar(): Char = readShort().toInt().toChar()
}

