package com.danawa.search.analysis.dict

import org.apache.logging.log4j.Logger
import org.elasticsearch.common.logging.Loggers
import java.util.Date
import java.util.HashMap

open class CommonDictionary<T, P>(
    private var systemDictionary: Dictionary<T, P>
) {
    private var createTime: Date = Date()
    private val dictionaryMap: MutableMap<String, SourceDictionary<*>> = HashMap()

    // systemDictionary를 재설정한다. dictionaryMap은 따로 외부에서 해주어야함.
    fun reset(dictionary: CommonDictionary<T, P>) {
        this.systemDictionary = dictionary.systemDictionary
        this.createTime = dictionary.createTime
    }

    fun find(token: CharSequence): List<T>? = systemDictionary.find(token)

    fun findPreResult(token: CharSequence): P? = systemDictionary.findPreResult(token)

    fun setPreDictionary(map: Map<CharSequence, P>) {
        systemDictionary.setPreDictionary(map)
    }

    fun size(): Int = systemDictionary.size()

    fun label(): String? = systemDictionary.label()

    fun seq(): Int = systemDictionary.seq()

    fun ignoreCase(): Boolean = (systemDictionary as TagProbDictionary).ignoreCase()

    @Suppress("UNCHECKED_CAST")
    fun <D : SourceDictionary<*>> getDictionary(dictionaryId: String, cls: Class<D>): D? {
        return try {
            dictionaryMap[dictionaryId] as? D
        } catch (ignore: Exception) {
            null
        }
    }

    fun getDictionaryMap(): MutableMap<String, SourceDictionary<*>> = dictionaryMap

    fun addDictionary(dictionaryId: String, dictionary: SourceDictionary<*>): SourceDictionary<*>? {
        val info = getDictionaryInfo(dictionary)
        logger.debug("addDictionary {} : {} [{} / {}]", dictionaryId, dictionary, info[0], info[1])
        return dictionaryMap.put(dictionaryId, dictionary)
    }

    fun appendAdditionalNounEntry(keySet: Set<CharSequence>, tokenType: String) {
        systemDictionary.appendAdditionalNounEntry(keySet, tokenType)
    }

    override fun toString(): String {
        return "${javaClass.simpleName}] createTime=$createTime, entry = ${systemDictionary.size()}, dictionaries = ${dictionaryMap.size}"
    }

    companion object {
        private val logger: Logger = Loggers.getLogger(CommonDictionary::class.java, "")

        @JvmStatic
        fun getDictionaryInfo(sourceDictionary: SourceDictionary<*>): IntArray {
            val ret = intArrayOf(0, 0)
            when (sourceDictionary) {
                is SetDictionary -> {
                    ret[0] = sourceDictionary.set().size
                }
                is SynonymDictionary -> {
                    ret[0] = sourceDictionary.map().keys.size
                    ret[1] = sourceDictionary.getWordSet().size
                }
                is SpaceDictionary -> {
                    ret[0] = sourceDictionary.map().keys.size
                    ret[1] = sourceDictionary.getWordSet().size
                }
                is CustomDictionary -> {
                    ret[0] = sourceDictionary.map().keys.size
                    ret[1] = sourceDictionary.getWordSet().size
                }
                is CompoundDictionary -> {
                    ret[0] = sourceDictionary.map().keys.size
                    ret[1] = sourceDictionary.getWordSet().size
                }
                is InvertMapDictionary -> {
                    ret[0] = sourceDictionary.map().keys.size
                }
                is MapDictionary -> {
                    ret[0] = sourceDictionary.map().keys.size
                }
            }
            return ret
        }
    }
}
